effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    vec2 ctr = center/1000.0 + 0.5;
    vec2 d = (acScreenNorm - ctr);
    d.x *= acScreenSize.x/acScreenSize.y;
    float r = length(d)*1.4142;
    float v = smoothstep(size, size-softness, r);
    vec3 outc = mix(color.rgb, c, mix(1.0, v, amount));
    gl_FragColor = vec4(outc,1.0)*src.a;
}
